cat > /app/output/gen.py <<'PY'
import sys, json, pathlib, numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot
from PIL import Image
r=Robot()
pathlib.Path('/app/output/spec.json').write_text(json.dumps(r.spec(),indent=2))
print('SPEC',json.dumps(r.spec()),flush=True)
i=0

def save(res):
 global i
 d=f'/app/output/obs{i:03d}'; i+=1
 res.save(d)
 for cam,im in res.last.items(): Image.fromarray(im).resize((640,480)).save(f'{d}/{cam}.png')
 print('RESULT',d,json.dumps(res.meta),flush=True)
 return res
obs=save(r.get_obs(include_depth=True,cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera','world_camera1')))
for line in sys.stdin:
 try:
  cmd=json.loads(line)
  if cmd['op']=='obs': obs=save(r.get_obs(include_depth=True,cameras=cmd.get('cameras',('head_camera','front_camera','left_camera','right_camera','observer_camera','world_camera1')),seconds=cmd.get('seconds',0)))
  elif cmd['op']=='ee': obs=save(r.submit('ee_pose',cmd['actions'],include_depth=True,video='both',note=cmd.get('note',''),cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera')))
  elif cmd['op']=='joint': obs=save(r.submit('joint_position',cmd['actions'],dt=cmd.get('dt',.05),include_depth=True,video='both',note=cmd.get('note','')))
  elif cmd['op']=='status': print(r.status(),flush=True)
 except Exception as e: print('ERROR',repr(e),flush=True)
PY
python -u /app/output/gen.py

